mapper.select:
SELECT COUNT(*) 
FROM comments 
WHERE "streamId" = #{streamId} 
  AND archived = false
  AND "createdAt" >= #{startDate}
  AND "createdAt" <= #{endDate}

SELECT COALESCE(SUM(
    CASE
        WHEN data IS NOT NULL AND jsonb_exists(data::jsonb, 'collisions')
        THEN jsonb_array_length(data::jsonb->'collisions')
        ELSE 0
    END
), 0)
FROM sp_crash_detection
WHERE stream_id = #{streamId}
  AND modify_time >= #{startDate}
  AND modify_time <= #{endDate}

SELECT COUNT(DISTINCT c.id) 
FROM commits c
JOIN branch_commits bc ON c.id = bc."commitId"
JOIN branches b ON bc."branchId" = b.id
WHERE b."streamId" = #{streamId}
  AND c."createdAt" >= #{startDate}
  AND c."createdAt" <= #{endDate}

SELECT 
    TO_CHAR(modify_time, 'MM-DD') as date,
    COUNT(*) as count
FROM sp_crash_detection 
WHERE stream_id = #{streamId}
  AND modify_time >= #{startDate}
  AND modify_time <= #{endDate}
GROUP BY TO_CHAR(modify_time, 'MM-DD'), DATE(modify_time)
ORDER BY DATE(modify_time)

SELECT
    '碰撞干扰' as category,
    COALESCE(SUM(
        CASE
            WHEN data IS NOT NULL AND jsonb_exists(data::jsonb, 'collisions')
            THEN jsonb_array_length(data::jsonb->'collisions')
            ELSE 0
        END
    ), 0) as count
FROM sp_crash_detection
WHERE stream_id = #{streamId}
  AND modify_time >= #{startDate}
  AND modify_time <= #{endDate}

UNION ALL

SELECT
    '不符合审查规范' as category,
    COALESCE(SUM(COALESCE(NULLIF(value_not_pass, ''), '0')::integer), 0)::bigint as count
FROM sp_revit_lod
WHERE stream_id = #{streamId}
  AND created_time >= #{startDate}
  AND created_time <= #{endDate}

UNION ALL

SELECT
    '属性参数缺失/错误' as category,
    COUNT(*) as count
FROM sp_revit_lod
WHERE stream_id = #{streamId}
  AND created_time >= #{startDate}
  AND created_time <= #{endDate}
  AND (value_pass IS NULL OR value_pass = '' OR value_not_pass IS NULL OR value_not_pass = '')

UNION ALL

SELECT
    '人工问题批注' as category,
    COUNT(*) as count
FROM comments
WHERE "streamId" = #{streamId}
  AND archived = false
  AND "createdAt" >= #{startDate}
  AND "createdAt" <= #{endDate}

SELECT 
    '第' || EXTRACT(WEEK FROM "createdAt") || '周' as week_label,
    EXTRACT(WEEK FROM "createdAt") as week_num,
    COUNT(*) as count
FROM comments 
WHERE "streamId" = #{streamId}
  AND "createdAt" >= #{startDate}
  AND "createdAt" <= #{endDate}
GROUP BY EXTRACT(WEEK FROM "createdAt")
ORDER BY EXTRACT(WEEK FROM "createdAt")

SELECT COUNT(*)
FROM sp_revit_lod
WHERE stream_id = #{streamId}
  AND COALESCE(NULLIF(value_not_pass, ''), '0')::integer != 0
  AND created_time >= #{startDate}
  AND created_time <= #{endDate}

SELECT COUNT(DISTINCT c.id)
FROM commits c
JOIN branch_commits bc ON c.id = bc."commitId"
JOIN branches b ON bc."branchId" = b.id
WHERE b."streamId" = #{streamId}
  AND c."createdAt" >= #{startDate}
  AND c."createdAt" <= #{endDate}

SELECT COUNT(DISTINCT tv.id)
FROM sp_template_version tv
JOIN sp_new_template nt ON tv.template_id = nt.id
WHERE nt.stream_id = #{streamId}
  AND tv.check_time >= #{startDate}
  AND tv.check_time <= #{endDate}

SELECT COUNT(*)
FROM comments
WHERE "streamId" = #{streamId}
  AND "createdAt" >= #{startDate}
  AND "createdAt" <= #{endDate}

SELECT COALESCE(SUM(
    CASE
        WHEN data IS NOT NULL AND jsonb_exists(data::jsonb, 'collisions')
        THEN jsonb_array_length(data::jsonb->'collisions')
        ELSE 0
    END
), 0)
FROM sp_crash_detection
WHERE stream_id = #{streamId}
  AND modify_time >= #{startDate}
  AND modify_time <= #{endDate}
